/**
 * The picture the "Alpine" ground paints, carried in the Module rather than in a Site's Media library.
 *
 * Inline, because the package build copies stylesheets and nothing else: a real file next to this one
 * would not reach the Site. That is the open end of "a Module may bring images" -- the ground contract
 * does not care which of the two it gets, so a file-shipping Module later changes nothing about it.
 *
 * One literal on one line rather than a readable concatenation, which no reader loses anything by: a
 * base64 payload has nothing to read, and 1300 joined string literals defeat the linter's parser.
 *
 * It stays small on purpose. A Module's picture travels in every install of that Module, wanted or not,
 * and the moment somebody edits the Theme it is taken into the Site's own Media library anyway.
 */
export const PHI_THEME_ALPINE_GROUND_IMAGE =
  "data:image/jpeg;base64,";
